 operator invite or a trust community\'s voucher.","oneOf":[{"\$ref":"#/\$defs/InviteAdmission"},{"\$ref":"#/\$defs/VoucherAdmission"}]},"InviteAdmission":{"title":"InviteAdmission","description":"Admission by an operator invite.","type":"object","additionalProperties":false,"required":["invite"],"properties":{"invite":{"type":"object","additionalProperties":false,"required":["token","claimCode"],"description":"Both halves of an invite from did-management/account/invite/issue.","properties":{"token":{"type":"string","minLength":16,"maxLength":256,"description":"The invite\'s single-use token."},"claimCode":{"type":"string","minLength":8,"maxLength":64,"description":"The invite\'s claim code, delivered to the registrant separately from the token."}}}}},"VoucherAdmission":{"title":"VoucherAdmission","description":"Admission by a trust community\'s voucher.","type":"object","additionalProperties":false,"required":["voucher"],"properties":{"voucher":{"\$ref":"#/\$defs/HostingVoucher"}}},"HostingVoucher":{"title":"HostingVoucher","description":"A trust community\'s signed statement that one DID may register an account with one hosting service. It is a credential: its own proof, by the community, for `assertionMethod`, carries the community\'s authority; the envelope proof of the register document carries only the registrant\'s.","type":"object","additionalProperties":false,"required":["type","id","issuer","validUntil","credentialSubject","proof"],"properties":{"@context":{"type":"array","maxItems":8,"items":{"type":"string","maxLength":512},"description":"JSON-LD contexts, when the community issues the voucher as a JSON-LD credential. Absent: a plain JSON credential."},"type":{"type":"array","minItems":1,"maxItems":8,"items":{"type":"string","minLength":1,"maxLength":128},"description":"Credential types. MUST include `DidHostingVoucher`; a validator does not check it."},"id":{"type":"string","minLength":1,"maxLength":256,"description":"The voucher\'s unique identifier. A consumer accepts each voucher once, keyed on (`issuer`, `id`), and keeps the record until `validUntil`."},"issuer":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^did:","description":"The trust community\'s DID. The consumer accepts vouchers only from issuers the target domain lists as trusted."},"validFrom":{"type":"string","format":"date-time","description":"Before this instant the voucher is not yet valid. Absent: valid from issue."},"validUntil":{"type":"string","format":"date-time","description":"After this instant the voucher is no longer accepted. REQUIRED, so a consumer\'s single-use record is bounded."},"credentialSubject":{"type":"object","additionalProperties":false,"required":["id","hostingService"],"description":"Whom the voucher admits, and where.","properties":{"id":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^did:","description":"The DID the voucher admits, without any `src` query parameter. MUST be the identity the register document\'s `issuer` names."},"hostingService":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^did:","description":"The DID of the hosting service the voucher is for: the register document\'s `recipient`. A voucher for one service is no use at another."},"domain":{"type":"string","minLength":1,"maxLength":253,"description":"When present, the only hosting domain the voucher admits on."}}},"proof":{"type":"object","additionalProperties":false,"required":["type","cryptosuite","verificationMethod","proofPurpose","proofValue"],"description":"The community\'s W3C Data Integrity proof over the voucher. Closed, so that a member this schema does not name is refused rather than dropped: a proof that lost a signed member could not be verified.","properties":{"type":{"type":"string","const":"DataIntegrityProof","description":"Always `DataIntegrityProof`."},"cryptosuite":{"type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9-]+\$","description":"The cryptosuite, e.g. `eddsa-jcs-2022`."},"created":{"type":"string","format":"date-time","description":"When the community signed the voucher."},"verificationMethod":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^did:","description":"The community key that signed the voucher: a verification method of `issuer`, under its `assertionMethod` relationship."},"proofPurpose":{"type":"string","const":"assertionMethod","description":"Always `assertionMethod`: a voucher is an attestation."},"proofValue":{"type":"string","minLength":1,"maxLength":1024,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$","description":"The signature, multibase base58btc."}}}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}}}}';

/// As [payloadSchemaJson], for the success-response variant.
const String responsePayloadSchemaJson =
    '{"\$schema":"https://json-schema.org/draft/2020-12/schema","\$ref":"#/\$defs/Response","\$defs":{"Response":{"\$anchor":"response","title":"DID Management — Account Register — response payload","description":"The account the service created and the DID record it published. Failures use trust-task-error, not this shape.","type":"object","additionalProperties":false,"required":["account","record"],"properties":{"account":{"\$ref":"#/\$defs/HostingAccount"},"record":{"\$ref":"#/\$defs/DidRecord"},"ext":{"\$ref":"#/\$defs/Ext"}}},"Ext":{"title":"Ext","description":"Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a reverse-DNS namespace; structure under each namespace is opaque to the framework.","type":"object","minProperties":1,"additionalProperties":true,"propertyNames":{"pattern":"^[a-z][a-z0-9-]*(\\\\.[a-z0-9-]+)+\$"}},"DidRecord":{"title":"DidRecord","type":"object","additionalProperties":false,"required":["mnemonic","owner","createdAt","updatedAt","versionCount"],"properties":{"mnemonic":{"type":"string","description":"Local path under which the DID is hosted (e.g. `alice`, `tenant/staff/alice`, `.well-known`). Compared by exact string equality (SPEC.md §4.8); producers SHOULD emit canonical form."},"owner":{"type":"string","description":"VID of the party that currently owns the record. Authorization to mutate the record is anchored on this field."},"createdAt":{"type":"string","format":"date-time","description":"RFC3339 timestamp of initial reservation."},"updatedAt":{"type":"string","format":"date-time","description":"RFC3339 timestamp of the most recent record mutation."},"versionCount":{"type":"integer","minimum":0,"description":"Number of log entries the host currently holds for the DID. `0` indicates a reservation with no published log yet."},"didId":{"type":"string","description":"Fully-qualified DID identifier resolved from the most recent log entry (e.g. `did:webvh:<scid>:host:path`). Absent when `versionCount === 0`."},"didUrl":{"type":"string","format":"uri","description":"Resolvable URL of the DID\'s log document (e.g. `https://did.example.com/alice/did.jsonl`). Stable across the record\'s lifetime: present from the initial reservation (`versionCount === 0`), it tells the owner where to publish the signed log and where resolvers fetch it. Distinct from `didId`, which only exists once a log entry has been published."},"method":{"type":"string","description":"DID method this record was registered under (e.g. `webvh`, `web`). When omitted, consumers MAY treat the record as legacy; SHOULD default to `webvh` only if their host predates the multi-method era."},"domain":{"type":"string","description":"Hosting domain (hostname) under which the DID resolves. Matches the host segment of the embedded DID identifier."},"disabled":{"type":"boolean","description":"When `true`, the DID is administratively disabled — the host serves a deactivation marker but retains content for recovery within the host\'s retention policy."},"totalResolves":{"type":"integer","minimum":0,"description":"Lifetime resolve counter, when the host exposes per-DID statistics."},"ext":{"\$ref":"#/\$defs/Ext","description":"Ecosystem-defined extension members per SPEC.md §4.5.1."}}},"HostingAccount":{"title":"HostingAccount","description":"One account on a DID hosting service: who holds it, how it was admitted, and where it stands in the service\'s inactivity lifecycle.","type":"object","additionalProperties":false,"required":["subject","role","domain","state","registeredAt"],"properties":{"subject":{"type":"string","minLength":1,"maxLength":2048,"pattern":"^did:","description":"The DID that holds the account, exactly as it authenticated when it registered. A `did:scid` subject is recorded without its `src` query parameter, which locates the log and is not part of the identity."},"role":{"type":"string","minLength":1,"maxLength":64,"description":"The role the hosting service holds the account under, in the service\'s own role vocabulary (opaque here, as in the acl/* family). A self-registered account starts under the service\'s most restricted DID-owner role; an administrator may later change it."},"domain":{"type":"string","minLength":1,"maxLength":253,"description":"The hosting domain the account was admitted on. A self-registered account may hold DIDs on this domain only."},"state":{"\$ref":"#/\$defs/AccountState"},"admission":{"type":"string","enum":["invite","voucher"],"description":"How the account was admitted: `invite`, an operator-issued invite; `voucher`, a voucher from a trust community the domain trusts. Absent for an account an administrator created directly."},"registeredAt":{"type":"string","format":"date-time","description":"When the account was created."},"lastActiveAt":{"type":"string","format":"date-time","description":"The last time the holder sent a task the service accepted, renewals included. A service MAY record this coarsely (for example at most once a day); it is a liveness signal, not an audit trail. Absent when the service has recorded none since registration."},"lastResolvedAt":{"type":"string","format":"date-time","description":"The last time any of the account\'s DIDs was resolved from the service, as far as the service knows. Absent when the service does not count resolutions toward liveness or has recorded none."},"disableAt":{"type":"string","format":"date-time","description":"When the account\'s DIDs will be disabled if nothing keeps the account alive before then. Present for an `active` or `warned` account that is subject to expiry; absent for an account that is not (one an administrator exempted, for example) and for a `disabled` one."},"purgeAt":{"type":"string","format":"date-time","description":"When a `disabled` account, its DIDs and its access are deleted. Present exactly when `state` is `disabled`."},"maxDidCount":{"type":"integer","minimum":0,"description":"The most DIDs the account may hold. Absent when the service does not state one."},"maxTotalSizeBytes":{"type":"integer","minimum":0,"description":"The most bytes of DID content the account may hold in total. Absent when the service does not state one."}}},"AccountState":{"title":"AccountState","type":"string","enum":["active","warned","disabled"],"description":"Where an account stands in the inactivity lifecycle. `active`: its DIDs are served. `warned`: its DIDs are served, `disableAt` is near, and the service has sent at least one expiry notice. `disabled`: its DIDs are not served; the holder may still renew until `purgeAt`. A purged account no longer exists and is reported as not found."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
  maxDocumentBytes: 1310720,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
